/**
 * RECORDED FIXTURE transport — explicitly labelled, opt-in only.
 *
 * These payloads were generated by executing the REAL deterministic kernel
 * (services/simulation/core) with the contract's demo trace and seed
 * 20261107, then serializing the results in the VQ-DEMO-SIM/1 response
 * shape. They exist so the playback UI can be developed, tested and
 * screen-captured while Agent A's HTTP endpoint (#32) is still unmerged.
 *
 * This is NOT a simulation implementation: no new simulation logic lives
 * here, responses are static recordings, and the UI must render a
 * "FIXTURE PLAYBACK" badge whenever this transport is active. The
 * production default transport is the real HTTP endpoint (client.ts).
 */
import type { DemoSimRequest, DemoSimResponse } from "./contract";
import type { DemoTransport } from "./client";
import recordedRun from "@/tests/mission-world/fixtures/demo-sim-seed20261107.json";
import recordedEmpty from "@/tests/mission-world/fixtures/demo-sim-seed20261107-empty.json";

const recorded = {
  run: recordedRun as unknown as DemoSimResponse,
  empty: recordedEmpty as unknown as DemoSimResponse,
};

function isEmptyTrace(body: DemoSimRequest): boolean {
  return body.operations.length === 0;
}

/**
 * Fixture transport: returns the recorded response whose operation list is a
 * prefix-compatible replay of the requested trace. Deterministic — identical
 * requests return identical deep copies.
 */
export const fixtureDemoTransport: DemoTransport = async (body) => {
  const base = isEmptyTrace(body) ? recorded.empty : recorded.run;
  return JSON.parse(JSON.stringify(base)) as DemoSimResponse;
};

export const FIXTURE_TRANSPORT_QUERY_PARAM = "fixture";
